CREATE OR REPLACE FUNCTION public.submit_security_report(report_input jsonb, workspace_user uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
IF jsonb_typeof(report_input)<>'object' OR octet_length(report_input::text)>20000 OR jsonb_typeof(report_input->'channel') IS DISTINCT FROM 'string' OR jsonb_typeof(report_input->'sender') IS DISTINCT FROM 'string' OR jsonb_typeof(report_input->'body') IS DISTINCT FROM 'string' OR report_input->>'channel' NOT IN ('email','sms','phone','website','social','other') OR length(report_input->>'sender')>500 OR length(report_input->>'body')>10000 OR (report_input ? 'url' AND (jsonb_typeof(report_input->'url') IS DISTINCT FROM 'string' OR length(report_input->>'url')>2000)) OR (report_input ? 'claimedOrgId' AND (jsonb_typeof(report_input->'claimedOrgId') IS DISTINCT FROM 'string' OR length(report_input->>'claimedOrgId')>200)) OR (length(trim(report_input->>'sender'))=0 AND coalesce(length(trim(report_input->>'url')),0)=0) THEN RAISE EXCEPTION 'Invalid report'; END IF;
INSERT INTO public.security_reports(recipient,input) VALUES(workspace_user,jsonb_build_object('channel',report_input->>'channel','sender',report_input->>'sender','body',report_input->>'body') || CASE WHEN report_input ? 'url' THEN jsonb_build_object('url',report_input->>'url') ELSE '{}'::jsonb END || CASE WHEN report_input ? 'claimedOrgId' THEN jsonb_build_object('claimedOrgId',report_input->>'claimedOrgId') ELSE '{}'::jsonb END);
END $$;
REVOKE ALL ON FUNCTION public.submit_security_report(jsonb,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_security_report(jsonb,uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.flagged_message_values(candidate_values text[], workspace_user uuid DEFAULT NULL) RETURNS text[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE result text[];
BEGIN
IF cardinality(candidate_values)>60 OR EXISTS(SELECT 1 FROM unnest(candidate_values) v WHERE length(v)>2000) THEN RAISE EXCEPTION 'Invalid check'; END IF;
WITH source AS (SELECT coalesce((SELECT payload FROM public.security_workspaces WHERE user_id=workspace_user),(SELECT payload FROM public.security_templates WHERE id='original')) AS payload), indicators AS (SELECT i->>'value' AS value FROM source, jsonb_array_elements(payload->'alerts') a, jsonb_array_elements(a->'indicators') i WHERE a->>'status' IN ('escalated','confirmed')) SELECT coalesce(array_agg(DISTINCT c),'{}'::text[]) INTO result FROM unnest(candidate_values) c WHERE EXISTS (SELECT 1 FROM indicators WHERE lower(regexp_replace(regexp_replace(regexp_replace(regexp_replace(value,'^https?://','','i'),'^www\.','','i'),'/$','','g'),'\s','','g'))=lower(regexp_replace(regexp_replace(regexp_replace(regexp_replace(c,'^https?://','','i'),'^www\.','','i'),'/$','','g'),'\s','','g')));
RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.flagged_message_values(text[],uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.flagged_message_values(text[],uuid) TO anon,authenticated,service_role;